/** Pemeriksa: id rujukan hidup di berkas aslinya, sumber unik, bukti dikenal, URL https, sumber_id dikenal. */
export function periksa(d) {
  const ids = (rel, f = (x) => x.baris) => new Set(f(j(rel)).map((x) => x.id));
  const org = ids('public/data/organisasi.json'), reg = ids('public/data/regulasi.json'), isu = ids('public/data/isu.json'), enb = ids('public/data/energi_baru.json'), pi = ids('public/data/pendanaan_internasional.json');
  const must = (set, arr, nama) => { for (const i of arr) if (!set.has(i)) throw new Error(`${nama} tidak ada: ${i}`); };
  must(org, d.rujukan.org_ids, 'org'); must(reg, d.rujukan.regulasi_ids, 'regulasi'); must(isu, d.rujukan.isu_ids, 'isu'); must(enb, d.rujukan.energi_baru_ids, 'energi_baru'); must(pi, d.rujukan.pendanaan_ids, 'pendanaan');
  must(org, d.pemain.map((p) => p.org_id).filter(Boolean), 'org pemain');
  must(org, d.pembangkit.proyek.flatMap((p) => p.pemilik.map((x) => x.org_id)).filter(Boolean), 'org pemilik');
  must(org, d.lng.terminal.map((x) => x.pemilik.org_id).filter(Boolean), 'org terminal');
  const sid = new Set(d.sumber.map((s) => s.id));
  if (sid.size !== d.sumber.length) throw new Error('id sumber ganda');
  for (const s of d.sumber) { if (!/^https:\/\//.test(s.url)) throw new Error('url ' + s.id); if (!BUKTI_SAH.includes(s.tingkat_bukti)) throw new Error('bukti ' + s.id); if (/antaranews/.test(s.url)) throw new Error('Antara ' + s.id); }
  const pakai = [...d.pembangkit.angka, d.pembangkit.fk_2024, ...d.pembangkit.proyek, ...d.pembangkit.ringkas_plnt, ...d.pembangkit.gasifikasi.angka, ...d.lng.terminal, d.lng.kargo, ...d.pipa.ruas, ...d.harga.kebijakan, ...d.harga.kontrak, d.neraca.pemanfaatan, d.neraca.sektor_domestik, d.neraca.defisit, d.neraca.produksi, ...d.neraca.alokasi, ...d.transisi.posisi, ...d.transisi.hidrogen, ...d.pemain.flatMap((p) => p.fakta), ...d.kebijakan.baru, ...d.isu.baru];
  for (const x of pakai) for (const k of ['sumber_id', 'sumber_id2']) if (x[k] && !sid.has(x[k])) throw new Error('sumber_id tak dikenal: ' + x[k]);
  if (!sid.has(d.pembangkit.gasifikasi.klaster_sumber_id) || !sid.has(d.transisi.hitung.ppa_sumber_id)) throw new Error('sumber klaster/ppa');
  for (const x of pakai) if (x.tingkat_bukti && ![...BUKTI_SAH, 'hipotesis', 'est'].includes(x.tingkat_bukti)) throw new Error('bukti butir ' + (x.id || x.k));
  if (d.neraca.defisit.baris.length !== 11) throw new Error('defisit harus 11 tahun');
  if (d.pembangkit.gasifikasi.klaster.length !== 6) throw new Error('klaster harus 6');
  if (d.neraca.pemanfaatan.baris[0].nilai + d.neraca.pemanfaatan.baris[1].nilai + d.neraca.pemanfaatan.baris[2].nilai < d.neraca.pemanfaatan.total - 1) throw new Error('total pemanfaatan');
  return { sumber: d.sumber.length, proyek: d.pembangkit.proyek.length, terminal: d.lng.terminal.length, pipa: d.pipa.ruas.length, pemain: d.pemain.length, celah: d.celah.length };
}

async function cekUrl() {
  const { ambil } = await import('../pipa/_panen_sopan.mjs');
  for (const s of SUMBER) { try { await ambil(s.url, { method: 'HEAD' }); console.log('OK ', s.id); } catch (e) { console.log('GAGAL', s.id, e.message); if (/403|429/.test(e.message)) break; } }
}

if (process.argv[1] === fileURLToPath(import.meta.url)) {
  const a = process.argv[2];
  if (a === '--bangun') { const d = bangun(); console.log(periksa(d)); fs.writeFileSync(path.join(ROOT, 'public/data/gas.json'), JSON.stringify(d, null, 1) + '\n'); }
  else if (a === '--selftest') console.log(periksa(bangun()));
  else if (a === '--cek-url') await cekUrl();
  else console.log('pakai: --bangun | --selftest | --cek-url');
}
